'use strict';

/**
 * Minimal structured JSON logger. One line per entry so CloudWatch Logs Insights can parse it.
 * Never log credentials, tokens or customer personal data.
 */

function write(level, message, fields) {
    const entry = { level, time: new Date().toISOString(), message, ...(fields || {}) };
    const line = JSON.stringify(entry);
    if (level === 'error') console.error(line);
    else if (level === 'warn') console.warn(line);
    else console.log(line);
}

module.exports = {
    debug: (message, fields) => {
        if (process.env.LOG_LEVEL === 'debug') write('debug', message, fields);
    },
    info: (message, fields) => write('info', message, fields),
    warn: (message, fields) => write('warn', message, fields),
    error: (message, fields) => write('error', message, fields),
};
